import{_ as a,o as i,c as t,a1 as e}from"./chunks/framework.BZ8LM4kv.js";const c=JSON.parse('{"title":"数据库表设计：从业务建模到数据完整性","description":"从业务场景出发，梳理数据库表设计中的常见约束、主键、外键、数据安全、删除策略、事务、订单快照与 UUID。","frontmatter":{"title":"数据库表设计：从业务建模到数据完整性","description":"从业务场景出发，梳理数据库表设计中的常见约束、主键、外键、数据安全、删除策略、事务、订单快照与 UUID。","date":"2026-11-25T00:00:00.000Z","category":"数据库","tags":["数据库","PostgreSQL","表设计","事务","数据安全"],"draft":false},"headers":[],"relativePath":"articles/database-table-design.md","filePath":"articles/database-table-design.md","lastUpdated":1795581925000}'),l={name:"articles/database-table-design.md"};function h(d,s,n,p,r,k){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="数据库表设计-从业务建模到数据完整性" tabindex="-1">数据库表设计：从业务建模到数据完整性 <a class="header-anchor" href="#数据库表设计-从业务建模到数据完整性" aria-label="Permalink to &quot;数据库表设计：从业务建模到数据完整性&quot;">​</a></h1><h2 id="_1-如何设计一张表" tabindex="-1">1. 如何设计一张表 <a class="header-anchor" href="#_1-如何设计一张表" aria-label="Permalink to &quot;1. 如何设计一张表&quot;">​</a></h2><p>我们应该从真实的业务场景出发。比如需要设计一个“用户登录”功能，那么可以先设计一个 <code>users</code> 表，包含 <code>id</code>、<code>account</code>、<code>password_hash</code> 等字段；其中 <code>users.id</code> 可以作为 <code>orders</code> 表的外键。</p><p>从这个例子可以看出，数据库设计应该从业务开始思考：需要哪些表、每张表有哪些字段，以及表与表之间通过哪些字段建立关系。</p><h2 id="_2-常见的五种约束" tabindex="-1">2. 常见的五种约束 <a class="header-anchor" href="#_2-常见的五种约束" aria-label="Permalink to &quot;2. 常见的五种约束&quot;">​</a></h2><p>约束的作用是保证数据的正确性和完整性，为字段或数据之间的关系设置规则。</p><h3 id="_2-1-五种常见的数据库约束" tabindex="-1">2.1 五种常见的数据库约束 <a class="header-anchor" href="#_2-1-五种常见的数据库约束" aria-label="Permalink to &quot;2.1 五种常见的数据库约束&quot;">​</a></h3><table tabindex="0"><thead><tr><th>约束</th><th>中文名称</th><th>主要作用</th></tr></thead><tbody><tr><td><code>PRIMARY KEY</code></td><td>主键约束</td><td>唯一标识一条数据</td></tr><tr><td><code>FOREIGN KEY</code></td><td>外键约束</td><td>保证表之间的引用有效</td></tr><tr><td><code>UNIQUE</code></td><td>唯一约束</td><td>防止字段值重复</td></tr><tr><td><code>NOT NULL</code></td><td>非空约束</td><td>不允许字段为 <code>NULL</code></td></tr><tr><td><code>CHECK</code></td><td>检查约束</td><td>限制字段值满足指定条件</td></tr></tbody></table><h4 id="主键约束" tabindex="-1">主键约束 <a class="header-anchor" href="#主键约束" aria-label="Permalink to &quot;主键约束&quot;">​</a></h4><p>主键具有以下性质：</p><ul><li>唯一：不能重复。</li><li>非空：不能为 <code>NULL</code>。</li></ul><p>一张表只能有一个主键约束，但主键可以由多个字段组成，也就是联合主键。</p><h4 id="外键约束" tabindex="-1">外键约束 <a class="header-anchor" href="#外键约束" aria-label="Permalink to &quot;外键约束&quot;">​</a></h4><p>例如订单表：</p><table tabindex="0"><thead><tr><th>id（主键）</th><th>user_id（外键）</th></tr></thead><tbody><tr><td>101</td><td>1</td></tr><tr><td>102</td><td>1</td></tr><tr><td>103</td><td>2</td></tr></tbody></table><p>其中 <code>orders.user_id</code> 引用了 <code>users.id</code>。如果尝试插入一个不存在的用户：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INSERT INTO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orders (id, user_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">104</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">999</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>因为 <code>users</code> 表中没有 <code>id = 999</code> 的记录，这次插入会失败。外键可以保证引用的数据确实存在。</p><h4 id="唯一约束" tabindex="-1">唯一约束 <a class="header-anchor" href="#唯一约束" aria-label="Permalink to &quot;唯一约束&quot;">​</a></h4><p>例如用户表：</p><table tabindex="0"><thead><tr><th>id</th><th>account（UNIQUE）</th></tr></thead><tbody><tr><td>1</td><td>zhangsan</td></tr><tr><td>2</td><td>lisi</td></tr><tr><td>3</td><td>wangwu</td></tr></tbody></table><p>将 <code>account</code> 设置为唯一约束后，就不能再次注册已经存在的账号。</p><h4 id="非空约束" tabindex="-1">非空约束 <a class="header-anchor" href="#非空约束" aria-label="Permalink to &quot;非空约束&quot;">​</a></h4><p>非空约束要求字段必须有值：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">account </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span></span></code></pre></div><p>需要注意：</p><ul><li><code>NULL</code> 表示缺少值，并不等于空字符串。</li><li><code>&#39;&#39;</code> 表示长度为 0 的空字符串。</li><li><code>NOT NULL</code> 只能限制 <code>NULL</code>，不能限制空字符串；如果业务上也不允许空字符串，还需要配合 <code>CHECK</code> 约束。</li></ul><h4 id="检查约束" tabindex="-1">检查约束 <a class="header-anchor" href="#检查约束" aria-label="Permalink to &quot;检查约束&quot;">​</a></h4><p>检查约束可以限制字段值必须满足某个条件。例如套餐价格不能为负数：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">price_fen </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BIGINT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> CHECK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (price_fen </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="_3-自增主键与并发安全" tabindex="-1">3. 自增主键与并发安全 <a class="header-anchor" href="#_3-自增主键与并发安全" aria-label="Permalink to &quot;3. 自增主键与并发安全&quot;">​</a></h2><p>数据库开发中常见的并发问题是：即使注册发生在不同时间，只要两个请求的查询和插入过程发生重叠，就可能产生冲突。</p><p>采用 Java 后端生成用户 ID 的方案确实可行，但如果生成策略不完善，可能产生主键冲突。更稳妥的做法是让数据库负责生成主键。</p><h3 id="_3-1-为什么数据库自动生成更好" tabindex="-1">3.1 为什么数据库自动生成更好 <a class="header-anchor" href="#_3-1-为什么数据库自动生成更好" aria-label="Permalink to &quot;3.1 为什么数据库自动生成更好&quot;">​</a></h3><p>PostgreSQL 可以通过 <code>GENERATED ... AS IDENTITY</code> 自动生成主键：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> users</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BIGINT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> GENERATED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ALWAYS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IDENTITY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    account </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> UNIQUE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    password_hash </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>数据库能够在并发插入时协调主键生成，避免应用层通过“查询最大 ID 再加一”这类方式造成竞争。</p><h3 id="_3-2-删除后的-id-是否应该复用" tabindex="-1">3.2 删除后的 ID 是否应该复用 <a class="header-anchor" href="#_3-2-删除后的-id-是否应该复用" aria-label="Permalink to &quot;3.2 删除后的 ID 是否应该复用&quot;">​</a></h3><p>如果删除了 <code>id = 2</code> 的用户，之后新用户注册时，通常应该继续生成新的 ID，而不是重新使用 <code>2</code>。</p><p>如果重复利用旧的主键，历史订单或其他关联数据可能被错误地连接到新用户。主键更适合作为记录的稳定标识，而不是连续编号展示给用户。</p><h2 id="_4-数据库安全" tabindex="-1">4. 数据库安全 <a class="header-anchor" href="#_4-数据库安全" aria-label="Permalink to &quot;4. 数据库安全&quot;">​</a></h2><p>用户密码应该经过专门的密码哈希算法处理后再存入数据库。</p><p>这里需要区分哈希（hash）和加密（encryption）：</p><ul><li><strong>加密</strong>：通常可以使用密钥解密，还原原始数据。</li><li><strong>哈希</strong>：通过算法生成摘要，设计目标不是直接还原原文。</li></ul><p>密码场景应该使用适合密码存储的算法，例如 BCrypt 或 Argon2id。登录时，系统使用用户输入的密码和数据库中的哈希值进行验证，而不是尝试“解密”出原密码。</p><h2 id="_5-外键删除规则" tabindex="-1">5. 外键删除规则 <a class="header-anchor" href="#_5-外键删除规则" aria-label="Permalink to &quot;5. 外键删除规则&quot;">​</a></h2><p>PostgreSQL 外键常见的删除规则如下：</p><table tabindex="0"><thead><tr><th>规则</th><th>行为</th><th>适合场景</th></tr></thead><tbody><tr><td><code>NO ACTION</code></td><td>存在违反外键约束的引用时拒绝操作（默认）</td><td>默认保护关联数据</td></tr><tr><td><code>RESTRICT</code></td><td>存在引用时立即阻止删除</td><td>严格限制父记录删除</td></tr><tr><td><code>CASCADE</code></td><td>自动删除所有关联的子记录</td><td>确实需要连带删除的从属数据</td></tr><tr><td><code>SET NULL</code></td><td>将子表对应外键设为 <code>NULL</code></td><td>允许子记录脱离父记录</td></tr><tr><td><code>SET DEFAULT</code></td><td>将子表对应外键设为默认值</td><td>存在有效默认管理值的场景</td></tr></tbody></table><h3 id="_5-1-on-delete-restrict" tabindex="-1">5.1 <code>ON DELETE RESTRICT</code> <a class="header-anchor" href="#_5-1-on-delete-restrict" aria-label="Permalink to &quot;5.1 \`ON DELETE RESTRICT\`&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FOREIGN KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (user_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REFERENCES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users (id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON DELETE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RESTRICT</span></span></code></pre></div><p>删除用户时，如果该用户仍然存在订单，数据库会阻止删除操作。</p><h3 id="_5-2-on-delete-cascade" tabindex="-1">5.2 <code>ON DELETE CASCADE</code> <a class="header-anchor" href="#_5-2-on-delete-cascade" aria-label="Permalink to &quot;5.2 \`ON DELETE CASCADE\`&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FOREIGN KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (user_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REFERENCES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users (id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON DELETE CASCADE</span></span></code></pre></div><p>删除用户时，数据库会自动删除关联订单。这个规则适合生命周期完全依附于父记录的从属数据，使用前需要确认级联范围。</p><h3 id="_5-3-on-delete-set-null" tabindex="-1">5.3 <code>ON DELETE SET NULL</code> <a class="header-anchor" href="#_5-3-on-delete-set-null" aria-label="Permalink to &quot;5.3 \`ON DELETE SET NULL\`&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FOREIGN KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (user_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REFERENCES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users (id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON DELETE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span></span></code></pre></div><p>用户被删除后，订单仍然保留，但订单中的 <code>user_id</code> 被设置为 <code>NULL</code>，表示订单不再关联该用户。使用这种规则时，外键字段必须允许 <code>NULL</code>。</p><h2 id="_6-物理删除和逻辑删除" tabindex="-1">6. 物理删除和逻辑删除 <a class="header-anchor" href="#_6-物理删除和逻辑删除" aria-label="Permalink to &quot;6. 物理删除和逻辑删除&quot;">​</a></h2><h3 id="_6-1-物理删除" tabindex="-1">6.1 物理删除 <a class="header-anchor" href="#_6-1-物理删除" aria-label="Permalink to &quot;6.1 物理删除&quot;">​</a></h3><p>物理删除是真正从数据库中删除一条记录，特点包括：</p><ul><li>数据库不再保存该行。</li><li>通常无法直接恢复。</li><li>外键可能阻止删除，也可能触发级联删除。</li><li>记录占用的空间需要数据库后续维护才能重新利用。</li><li>物理删除不代表备份、WAL 等历史介质中的数据会立即消失。</li></ul><h3 id="_6-2-逻辑删除" tabindex="-1">6.2 逻辑删除 <a class="header-anchor" href="#_6-2-逻辑删除" aria-label="Permalink to &quot;6.2 逻辑删除&quot;">​</a></h3><p>逻辑删除不真正删除记录，而是修改一个字段，表示这条记录已经被删除或停用。例如使用 <code>account_status</code> 表示账号状态：</p><ul><li><code>ACTIVE</code>：正常使用。</li><li><code>BANNED</code>：管理员封禁。</li><li><code>DELETED</code>：账号已注销。</li></ul><p>对于订单、支付流水、审计记录等需要长期追溯的数据，逻辑删除通常更容易保留历史上下文。</p><p>不推荐随意使用物理级联删除：如果之后需要核对流水、审计操作或分析客户行为，级联删除可能让历史记录难以追踪。</p><h2 id="_7-事务" tabindex="-1">7. 事务 <a class="header-anchor" href="#_7-事务" aria-label="Permalink to &quot;7. 事务&quot;">​</a></h2><p>事务是把多个数据库操作捆绑成一个整体：要么全部成功，要么全部失败，不允许只完成其中一部分。</p><p>只有事务成功时才提交；如果执行过程中失败，就回滚已经执行的操作。</p><h3 id="_7-1-事务的三个基本操作" tabindex="-1">7.1 事务的三个基本操作 <a class="header-anchor" href="#_7-1-事务的三个基本操作" aria-label="Permalink to &quot;7.1 事务的三个基本操作&quot;">​</a></h3><p>在 PostgreSQL 中，需要认识三个关键字：</p><table tabindex="0"><thead><tr><th>SQL</th><th>含义</th></tr></thead><tbody><tr><td><code>BEGIN</code></td><td>开始事务</td></tr><tr><td><code>COMMIT</code></td><td>提交事务</td></tr><tr><td><code>ROLLBACK</code></td><td>回滚事务</td></tr></tbody></table><p>例如转账操作：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BEGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accounts</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accounts</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COMMIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>如果任意一步失败，就应该执行 <code>ROLLBACK</code>，避免只扣款而没有完成收款。</p><h3 id="_7-2-事务的四大特性-acid" tabindex="-1">7.2 事务的四大特性（ACID） <a class="header-anchor" href="#_7-2-事务的四大特性-acid" aria-label="Permalink to &quot;7.2 事务的四大特性（ACID）&quot;">​</a></h3><ul><li><strong>A：Atomicity，原子性</strong> —— 一个事务中的操作要么全部成功，要么全部失败。</li><li><strong>C：Consistency，一致性</strong> —— 事务执行前后，数据库都必须满足约束和业务规则。</li><li><strong>I：Isolation，隔离性</strong> —— 并发执行的事务之间按照隔离级别控制相互影响。</li><li><strong>D：Durability，持久性</strong> —— 事务提交成功后，数据库应保证已提交的数据持久保存。</li></ul><h2 id="_8-订单快照" tabindex="-1">8. 订单快照 <a class="header-anchor" href="#_8-订单快照" aria-label="Permalink to &quot;8. 订单快照&quot;">​</a></h2><p>历史订单应该保存交易发生时的数据，而不能完全依赖随时可能改变的商品或套餐信息。</p><p>例如，订单表可以增加以下快照字段：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plan_name_snapshot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">duration_days_snapshot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INTEGER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span></span></code></pre></div><p>即使套餐名称、价格或时长后来发生变化，历史订单仍然可以展示当时交易使用的内容。</p><h2 id="_9-uuid" tabindex="-1">9. UUID <a class="header-anchor" href="#_9-uuid" aria-label="Permalink to &quot;9. UUID&quot;">​</a></h2><p>UUID（Universally Unique Identifier）是通用唯一识别码。</p><p>它的常见特点包括：</p><ol><li>不需要先查询数据库，应用可以直接生成。</li><li>在合理使用的前提下，重复概率极低。</li><li>相比连续数字 ID，更难从标识符推测数据规模或记录顺序。</li></ol><p>UUID 可以用于幂等键、避免重复下单、外部资源标识以及凭证构建等场景。不过它的存储空间和索引性能特征与整数主键不同，应该根据业务规模和数据库特性选择。</p>`,87)])])}const E=a(l,[["render",h]]);export{c as __pageData,E as default};
